      {
        "atom_id": "atom::fe8a34ad7e972c4f4e598847",
        "source_handle": "P0030",
        "field_path": [
          "study_summary_A",
          "approach"
        ],
        "value": "采用单臂、前瞻性、II期临床试验设计。纳入标准为BCLC A–B期HCC、ECOG评分0–1、器官功能良好且在TACE后2周及MWA后1周影像学评估均达到mRECIST完全缓解的患者。排除既往接受过其他免疫调节剂、存在活动性感染或严重合并症者。所有患者在接受TACE和MWA后2周内开始接受特瑞普利单抗治疗，持续6个月。随访直至复发、死亡或研究结束。统计分析计划包括Kaplan-Meier估计RFS和OS，Cox比例风险模型计算HR，以及描述性统计次要终点。样本量计算基于历史数据预期中位RFS从15.5个月提升至27个月（HR=0.57），需30名参与者以检测显著差异。",
        "role": "evidence",
        "snapshot_ids": [
          "snapshot::a54c4177705f169c0abc452e"
        ]
      },
      {
        "atom_id": "atom::b75b6c531806168ee3c5a352",
        "source_handle": "P0030",
        "field_path": [
          "study_summary_A",
          "contribution_and_limits"
        ],
        "value": {
          "contribution": "提供了针对特定亚群（BCLC A–B期，TACE+MWA后CR）的辅助免疫治疗标准化方案细节，包括药物剂量、疗程（6个月短程）、评估时间点及安全性监测流程。",
          "limits": "作为方案文件，缺乏实际临床结局数据；单臂设计无法提供因果推断证据，依赖外部历史数据进行比较；样本量较小（n=30），可能限制对罕见不良反应的检测能力及结果的普遍适用性；随访时间较短，无法评估长期“尾部效应”。"
        },
        "role": "evidence",
